const smallScreen = window.innerWidth < 900;

class OutpostScene extends Phaser.Scene {
  constructor() {
      super("Outpost");
        }

          create() {
              buildWorld(this);
                  this.player = createPlayer(this);
                      this.solids.forEach(s => this.physics.add.collider(this.player, s));

                          this.keys = this.input.keyboard.addKeys({
                                up: "W", down: "S", left: "A", right: "D",
                                      up2: "UP", down2: "DOWN", left2: "LEFT", right2: "RIGHT",
                                            interact: "E", space: "SPACE"
                                                });

                                                    setupMobileControls(() => this.interact());

                                                        if (smallScreen) {
                                                              this.cameras.main.setBounds(0, 0, 960, 640);
                                                                    this.cameras.main.startFollow(this.player, true, 0.1, 0.1);
                                                                        }

                                                                            planEvents();
                                                                                updateDashboard();
                                                                                    state.paused = true;
                                                                                        showHelp(true);
                                                                                          }

                                                                                            update() {
                                                                                                if (state.over || state.paused) {
                                                                                                      stopPlayer(this);
                                                                                                            return;
                                                                                                                }
                                                                                                                    movePlayer(this);

                                                                                                                        if (Phaser.Input.Keyboard.JustDown(this.keys.interact) ||
                                                                                                                                Phaser.Input.Keyboard.JustDown(this.keys.space)) {
                                                                                                                                      this.interact();
                                                                                                                                          }

                                                                                                                                              const near = nearestBuilding(this.player);
                                                                                                                                                  hint(near
                                                                                                                                                        ? near.name + ": " + near.job + (near.cost ? " (" + near.cost + " power)" : "")
                                                                                                                                                              : "Walk up to a building, then press INTERACT.");
                                                                                                                                                                }

                                                                                                                                                                  interact() {
                                                                                                                                                                      if (state.over || state.paused) return;
                                                                                                                                                                          const b = nearestBuilding(this.player);
                                                                                                                                                                              if (!b) {
                                                                                                                                                                                    message("Move closer to a building first.");
                                                                                                                                                                                          return;
                                                                                                                                                                                              }
                                                                                                                                                                                                  useBuilding(this, b);
                                                                                                                                                                                                    }
                                                                                                                                                                                                    }

                                                                                                                                                                                                    function showHelp(atStart) {
                                                                                                                                                                                                      showOverlay("How to play", HELP_TEXT, "", [
                                                                                                                                                                                                          {
                                                                                                                                                                                                                label: atStart ? "Start mission" : "Back to game",
                                                                                                                                                                                                                      note: "",
                                                                                                                                                                                                                            onClick: () => {
                                                                                                                                                                                                                                    hideOverlay();
                                                                                                                                                                                                                                            if (atStart) startDay();
                                                                                                                                                                                                                                                    else state.paused = false;
                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                ], atStart);
                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                function startDay() {
                                                                                                                                                                                                                                                                  state.paused = false;
                                                                                                                                                                                                                                                                    state.power = DAILY_POWER;
                                                                                                                                                                                                                                                                      dayStart = { science: state.science };
                                                                                                                                                                                                                                                                        updateDashboard();
                                                                                                                                                                                                                                                                          message("Day " + state.day + " begins. Check your life-support systems!");

                                                                                                                                                                                                                                                                            const ev = todaysEvent();
                                                                                                                                                                                                                                                                              if (!ev) return;

                                                                                                                                                                                                                                                                                state.paused = true;
                                                                                                                                                                                                                                                                                  playSound("event");
                                                                                                                                                                                                                                                                                    const choose = option => () => {
                                                                                                                                                                                                                                                                                        const result = applyEffects(option.fx);
                                                                                                                                                                                                                                                                                            hideOverlay();
                                                                                                                                                                                                                                                                                                state.paused = false;
                                                                                                                                                                                                                                                                                                    updateDashboard();
                                                                                                                                                                                                                                                                                                        message(option.label + ". " + result);
                                                                                                                                                                                                                                                                                                            if (state.health <= 0) finish(false);
                                                                                                                                                                                                                                                                                                              };
                                                                                                                                                                                                                                                                                                                showOverlay(ev.title, ev.text, ev.source, [
                                                                                                                                                                                                                                                                                                                    { label: ev.a.label, note: ev.a.note, onClick: choose(ev.a) },
                                                                                                                                                                                                                                                                                                                        { label: ev.b.label, note: ev.b.note, onClick: choose(ev.b) }
                                                                                                                                                                                                                                                                                                                          ]);
                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                          function finishDay() {
                                                                                                                                                                                                                                                                                                                            if (state.over || state.paused) return;

                                                                                                                                                                                                                                                                                                                              if (state.power >= 2) {
                                                                                                                                                                                                                                                                                                                                  state.paused = true;
                                                                                                                                                                                                                                                                                                                                      playSound("caution");
                                                                                                                                                                                                                                                                                                                                          showOverlay("Before you end the day",
                                                                                                                                                                                                                                                                                                                                                "You still have " + state.power + " power left. It does not carry over to tomorrow, so use it first if you can.", "", [
                                                                                                                                                                                                                                                                                                                                                      { label: "Keep playing", note: "Go back and use your power.", onClick: () => { hideOverlay(); state.paused = false; } },
                                                                                                                                                                                                                                                                                                                                                            { label: "End day anyway", note: "", onClick: () => { hideOverlay(); state.paused = false; closeDay(); } }
                                                                                                                                                                                                                                                                                                                                                                ]);
                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                        closeDay();
                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                        function closeDay() {
                                                                                                                                                                                                                                                                                                                                                                          const report = endDay();
                                                                                                                                                                                                                                                                                                                                                                            updateDashboard();

                                                                                                                                                                                                                                                                                                                                                                              if (state.health <= 0) return finish(false);
                                                                                                                                                                                                                                                                                                                                                                                if (state.day >= DAYS) return finish(true);

                                                                                                                                                                                                                                                                                                                                                                                  const done = state.day;
                                                                                                                                                                                                                                                                                                                                                                                    state.paused = true;
                                                                                                                                                                                                                                                                                                                                                                                      playSound("day");
                                                                                                                                                                                                                                                                                                                                                                                        showOverlay("Day " + done + " complete", dayComment(report), "", [
                                                                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                                                                  label: "Start day " + (done + 1),
                                                                                                                                                                                                                                                                                                                                                                                                        note: "",
                                                                                                                                                                                                                                                                                                                                                                                                              onClick: () => {
                                                                                                                                                                                                                                                                                                                                                                                                                      hideOverlay();
                                                                                                                                                                                                                                                                                                                                                                                                                              state.day++;
                                                                                                                                                                                                                                                                                                                                                                                                                                      startDay();
                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                  ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                  function finish(survived) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                    state.over = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                      state.paused = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                        let title, text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!survived) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                              playSound("lose");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  title = "Mission ended early";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      text = "The crew could not stay healthy. Try a different plan next time: life support comes first, and a weak shield adds up.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else if (state.science >= SCIENCE_GOAL) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            playSound("win");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                title = "Mission success!";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    text = "The crew survived " + DAYS + " days and you collected " + state.science + " science points.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          playSound("day");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              title = "Crew survived, goal missed";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  text = "You got " + state.science + " of " + SCIENCE_GOAL + " science points. Try giving the lab more power on calm days.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      showOverlay(title, text, "", [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          { label: "Play again", note: "", onClick: () => location.reload() }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("end-day").addEventListener("click", finishDay);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("help").addEventListener("click", () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (state.paused || state.over) return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                state.paused = true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  showHelp(false);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.getElementById("sound-btn").addEventListener("click", toggleSound);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  updateSoundButton();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  new Phaser.Game({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    type: Phaser.AUTO,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      width: 960,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        height: 640,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          parent: "game-container",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            backgroundColor: "#777d91",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              physics: { default: "arcade", arcade: { debug: false } },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                scale: smallScreen
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ? { mode: Phaser.Scale.RESIZE }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        : { mode: Phaser.Scale.FIT, autoCenter: Phaser.Scale.CENTER_BOTH },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          scene: [OutpostScene]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });